INSERT INTO imaging_result (id, patient_id, order_id, modality, exam_name, body_region, performed_at, reported_at, radiologist_name, radiologist_id, technique, findings, conclusion, status, image_count, critical, reviewed_at, reviewed_by_id) VALUES
    ('46b4363a-51a4-5eae-9151-05948f291573', '50c8f3fa-ea66-581a-9207-f9c4c7131d26', '92eb9648-eeb5-59b3-8307-b3c592976d73', 'CT', 'TK głowy bez kontrastu', 'Głowa', now() - interval '5 hours', now() - interval '4 hours', 'lek. Grzegorz Nowicki', NULL, 'Badanie TK głowy bez podania środka kontrastowego, warstwy 5 mm.', 'W obrębie prawego płata skroniowego widoczne niewielkie ognisko stłuczenia mózgu. Bez cech aktywnego krwawienia śródczaszkowego. Struktury linii pośrodkowej bez przemieszczenia.', 'Stłuczenie mózgu prawego płata skroniowego bez cech krwawienia czynnego. Zalecana kontrola kliniczna i ewentualne badanie kontrolne za 24h.', 'final', 64, TRUE, NULL, NULL),
    ('1d2ddc8a-a36d-5ba4-a50c-3026e03f7cf9', 'a8500c41-1152-563d-b249-363417666099', 'e2da861b-a85e-5717-9eda-95f4cf78924e', 'MRI', 'RM głowy z kontrastem', 'Głowa', now() - interval '96 hours', now() - interval '93 hours', 'lek. Grzegorz Nowicki', NULL, 'Badanie RM głowy z podaniem środka kontrastowego, sekwencje DWI, FLAIR, T1, T2.', 'W obrębie lewej półkuli mózgu, w zakresie unaczynienia tętnicy środkowej mózgu, widoczne rozległe ognisko niedokrwienne o wymiarach ok. 4x3 cm, z restrykcją dyfuzji.', 'Świeże ognisko niedokrwienne lewej półkuli mózgu, zgodne z obrazem klinicznym udaru.', 'final', 120, FALSE, NULL, NULL),
    ('202eded7-4eff-5810-8896-9dc66d5a7c88', '7466c824-06b6-57f2-8bae-2f20f77d64b6', '3a29c7db-b1fd-5cf1-88d8-78a9ef00d3ba', 'ANGIOGRAPHY', 'Koronarografia', 'Tętnice wieńcowe', now() - interval '20 hours', now() - interval '19 hours', 'dr n. med. Piotr Wiśniewski', NULL, 'Koronarografia z dostępu promieniowego prawego.', 'Istotne zwężenie (90%) gałęzi okalającej lewej tętnicy wieńcowej. Pozostałe naczynia wieńcowe bez istotnych zwężeń.', 'Krytyczne zwężenie gałęzi okalającej - wykonano angioplastykę z implantacją stentu.', 'final', 30, TRUE, NULL, NULL),
    ('54b378dd-5c33-5a88-9463-192ce3f37e67', '17a3dd05-d7d5-5211-ba70-0fc6e51cc476', 'c8e8a14e-b4d1-521f-b7e3-5e5aed1fab16', 'USG', 'USG jamy brzusznej', 'Jama brzuszna', now() - interval '49 hours', now() - interval '48 hours', 'lek. Grzegorz Nowicki', NULL, 'Badanie USG jamy brzusznej, sonda convex 3.5 MHz.', 'Pęcherzyk żółciowy z licznymi złogami, ściana pogrubiała do 4 mm. Wątroba, trzustka, śledziona i nerki bez zmian ogniskowych.', 'Kamica pęcherzyka żółciowego z cechami przewlekłego zapalenia.', 'final', 12, FALSE, NULL, NULL),
    ('0c7552fd-1280-5d0d-b642-74547f544d67', '2350ac70-4b44-51c1-8be3-5b736e27a2c9', NULL, 'USG', 'USG jamy brzusznej', 'Jama brzuszna', now() - interval '27 hours', now() - interval '26 hours', 'lek. Grzegorz Nowicki', NULL, 'Badanie USG jamy brzusznej, ocena okolicy prawego dołu biodrowego.', 'W prawym dole biodrowym poszerzony wyrostek robaczkowy (12 mm) z cechami nacieku zapalnego okolicznej tkanki tłuszczowej.', 'Obraz zgodny z ostrym zapaleniem wyrostka robaczkowego.', 'final', 8, FALSE, NULL, NULL);
